    /// <summary>An employee files a work expense so it can be decided and reimbursed.</summary>
    /// <implements>use-case/spending.submit-expense</implements>
    internal sealed partial class SubmitExpenseEndpoint : IEndpoint
    {
        /// <inheritdoc />
        public void MapEndpoint(IEndpointRouteBuilder endpoints)
        {
            endpoints.MapPost("/api/expenses", HandleAsync)
                .WithName("submitExpense")
                .WithSummary("Submit Expense")
                .WithDescription("An employee files a work expense so it can be decided and reimbursed.")
                .Produces<SubmitExpenseResponseModel>(StatusCodes.Status201Created)
                .ProducesProblem(StatusCodes.Status400BadRequest)
                .ProducesProblem(StatusCodes.Status401Unauthorized)
                .ProducesProblem(StatusCodes.Status403Forbidden)
                .ProducesProblem(StatusCodes.Status422UnprocessableEntity);
        }

        private static async Task<Results<Created<SubmitExpenseResponseModel>, ProblemHttpResult>> HandleAsync(
            SubmitExpenseRequest request,
            ClaimsPrincipal user,
            ICommandMediator mediator,
            CancellationToken cancellationToken)
        {
            if (!ExpenseId.TryParse(request.ExpenseId.ToString(), null, out var expenseId))
            {
                return TypedResults.Problem(
                    title: "Invalid expense id.",
                    detail: $"The expense id '{request.ExpenseId}' is not a valid expense id.",
                    statusCode: StatusCodes.Status400BadRequest);
            }

            ReceiptId? receiptId = null;
            if (request.ReceiptId is not null)
            {
                if (!ReceiptId.TryParse(request.ReceiptId.Value.ToString(), null, out var parsed))
                {
                    return TypedResults.Problem(
                        title: "Invalid receipt id.",
                        detail: $"The receipt id '{request.ReceiptId.Value}' is not a valid receipt id.",
                        statusCode: StatusCodes.Status400BadRequest);
                }

                receiptId = parsed;
            }

            if (request.Lines is null)
            {
                return TypedResults.Problem(
                    title: "Missing lines.",
                    detail: "The lines list is required.",
                    statusCode: StatusCodes.Status400BadRequest);
            }

            List<ExpenseSplit>? splitsRows = null;
            if (request.Splits is not null)
            {
                splitsRows = new List<ExpenseSplit>(request.Splits.Length);
                foreach (var row in request.Splits)
                {
                    if (!ExpenseCategory.TryFromCode(row.Category, out var splitsCategory))
                    {
                        return TypedResults.Problem(
                            title: "Unknown expense category.",
                            detail: $"The category '{row.Category}' names no expense category.",
                            statusCode: StatusCodes.Status400BadRequest);
                    }

                    splitsRows.Add(new ExpenseSplit(
                        CostCenter: row.CostCenter,
                        Amount: row.Amount,
                        Category: splitsCategory
                    ));
                }
            }

            var linesRows = new List<ExpenseLine>(request.Lines.Length);
            foreach (var row in request.Lines)
            {
                linesRows.Add(new ExpenseLine(
                    Category: row.Category,
                    Amount: row.Amount
                ));
            }

            var result = await mediator.SendAsync(
                new SubmitExpenseCommand(
                    ExpenseId: expenseId,
                    Amount: request.Amount,
                    Currency: request.Currency,
                    Category: request.Category,
                    ReceiptId: receiptId,
                    EmployeeId: ActorClaims.ReadActorId<Guid>(user, "employee"),
                    Labels: request.Labels,
                    Splits: splitsRows,
                    Note: request.Note,
                    ImportId: request.ImportId,
                    Lines: linesRows
                ),
                cancellationToken);

            return TypedResults.Created(
                $"/api/expenses/{result.ExpenseId}",
                ShapeSubmitExpenseResponse(result));
        }
    }

